$(document).ready(function(){$("#stock").addClass("selected"),$("#stock a").addClass("active"),initView()});const componentFilters={locations:"",products:""};function initView(){fetchStats(),fetchStatus(),fetchList()}function fetchStats(){sendAjax({endpoint:"/Stock/stats",type:"POST",data:componentFilters,beforeSend:function(){loadingStats("stats")},onSuccess:t=>{setTimeout(()=>{t.success?buildStats(t.data):Notify(2,t.message)},1200)}})}function fetchStatus(){sendAjax({endpoint:"/Stock/status",onSuccess:t=>{setTimeout(()=>{t.success?buildStatus(t.data):Notify(2,t.message)},1200)}})}function fetchList(){sendAjax({endpoint:"/Stock/list",type:"POST",data:componentFilters,beforeSend:function(){loadingTable("lists")},onSuccess:t=>{setTimeout(()=>{t.success?buildList(t.data):Notify(2,t.message)},1200)}})}function buildList(t){let s="";t.forEach(t=>{s+=`<tr class="fw-semibold bg-info-subtle">\n            <td>${t.producto}</td>\n            <td></td>\n            <td class="text-nowrap">\n                <div class="d-flex align-items-center justify-content-end">\n                    <span class="material-symbols-outlined icon-fill text-primary">weight</span>\n                    <span class="ms-3">${t.totalCantidad} Lbs</span>\n                </div>\n            </td>\n            <td class="text-end">${t.totalToneladas} T</td>\n            <td class="text-end">\n                <div class="d-flex align-items-center justify-content-end">\n                    <span class="material-symbols-outlined icon-fill text-primary">package_2</span>\n                    <span class="ms-3">${t.totalPaquetes}</span>\n                </div>\n            </td>\n            <td>-</td>\n            <td></td>\n        </tr>`,t.details.forEach(e=>{t.productoId;const n=e.subproductoId;s+=`<tr class="bg-light">\n                <td class="ps-5 fw-bold">\n                    <div class="d-flex align-items-center">\n                        <span class="material-symbols-outlined icon-fill fs-2 text-gray-100">circle</span>\n                        <span class="ms-3">${e.subproducto}</span>\n                    </div>\n                </td>\n                <td></td>\n                <td class="text-end">${e.totalCantidad} Lbs</td>\n                <td class="text-end">${e.totalToneladas} T</td>\n                <td class="text-end">${e.totalPaquetes}</td>\n                <td>-</td>\n                <td>\n                    <div class="d-flex align-items-center justify-content-center user-select-none">\n                        <div class="d-flex align-items-center">\n                            <a href="../Stock/${n}" class="material-symbols-outlined edit h3 text-gray-100" title="Administrar">settings</a>\n                        </div>\n                    </div>\n                </td>\n            </tr>`,e.details.forEach(t=>{const e=t.ultima_actualizacion,n=new Date(e.replace(" ","T"));s+=`<tr>\n                    <td class="ps-5">\n                        <div class="ps-5">\n                            <span class="material-symbols-outlined icon-fill fs-2 text-gray">circle</span>\n                            <span class="ms-3"> ${t.ubicacion}</span>\n                        </div>\n                    </td>\n                    <td>${t.presentacion}</td>\n                    <td class="text-end">${t.cantidad} Lbs</td>\n                    <td class="text-end">${t.toneladas} T</td>\n                    <td class="text-end">${t.paquetes}</td>\n                    <td>\n                        <div class="fw-bold fs-3">${formatoRelativo(n)}</div>\n                        <div class="text-muted">${formatoFechaCorta(n)}</div>\n                    </td>\n                    <td></td>\n                </tr>`})})});let e=`<div class="table-responsive border rounded-3 shadow mt-3">\n            <table class="table align-middle mb-0 text-dark fs-4">\n                <thead>\n                    <tr>\n                        <th>Producto / Subproducto / Ubicación</th>\n                        <th>Presentación</th>\n                        <th class="text-end">Cantidad (Libras)</th>\n                        <th class="text-end">Cantidad (Toneladas)</th>\n                        <th class="text-end">Paquetes</th>\n                        <th>Última Actualización</th>\n                        <th class="text-center">Acciones</th>\n                    </tr>\n                </thead>\n                <tbody>\n                ${s}\n                </tbody>\n            </table>\n        </div>`;$("#lists").empty().html(e)}function buildStatus(t){const s=t.locations,e=t.products;let n="",a="";s.forEach(t=>{n+=`<option value="${t.id}">${t.name}</option>`}),e.forEach(t=>{a+=`<option value="${t.id}">${t.name}</option>`});let d=`\n    <div class="d-flex flex-column flex-md-row gap-2">\n            <select class="form-select form-select-lg rounded-3 mb-md-0" id="products">\n                <option value="">Todos los Productos</option>\n                ${a}\n            </select>\n            <select class="form-select form-select-lg rounded-3 mb-md-0" id="locations">\n                <option value="">Todas las ubicaciones</option>\n                ${n}\n            </select>\n        </div>`;$("#status").empty().html(d)}function buildStats(t){const s=t.last_update||"";let e="";s&&(e=new Date(s.replace(" ","T")));let n=`\n    <div class="row g-3 mb-3 user-select-none">\n            <div class="col-md-3">\n                <div class="card shadow border mb-1 card-hover h-100">\n                    <div class="card-body d-flex align-items-center gap-3 p-2">\n                        <div class="bg-primary-subtle rounded-4 p-3 d-flex justify-content-center align-items-center">\n                            <span class="material-symbols-outlined text-primary" style="font-size: 2rem;">package_2</span>\n                        </div>\n                        <div>\n                            <div class="text-muted fw-bold h5">Total Almacenado</div>\n                            <div class="fw-semibold h4">${Number((t.total_quantity/2200).toFixed(3))} T</div>\n                            <div class="text-muted h6">${Number(t.total_quantity)||0} Lbs</div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class="col-md-3">\n                <div class="card shadow border mb-1 card-hover h-100">\n                    <div class="card-body d-flex align-items-center gap-3 p-2">\n                        <div class="bg-warning-subtle rounded-4 p-3 d-flex justify-content-center align-items-center">\n                            <span class="material-symbols-outlined text-warning" style="font-size: 2rem;">package</span>\n                        </div>\n                        <div>\n                            <div class="text-muted fw-bold h5">Total Paquetes</div>\n                            <div class="fw-semibold h4">${Number(t.total_packages)||0}</div>\n                            <div class="text-muted h6">Paquetes disponibles</div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class="col-md-3">\n                <div class="card shadow border mb-1 card-hover h-100">\n                    <div class="card-body d-flex align-items-center gap-3 p-2">\n                        <div class="bg-success-subtle rounded-4 p-3 d-flex justify-content-center align-items-center">\n                            <span class="material-symbols-outlined text-success" style="font-size: 2rem;">content_paste</span>\n                        </div>\n                        <div>\n                            <div class="text-muted fw-bold h5">Productos Activos</div>\n                            <div class="fw-semibold h4">${t.total_items||0}</div>\n                            <div class="text-muted h6">Productos registrados</div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class="col-md-3">\n                <div class="card shadow border mb-1 card-hover h-100">\n                    <div class="card-body d-flex align-items-center gap-3 p-2">\n                        <div class="bg-info-subtle rounded-4 p-3 d-flex justify-content-center align-items-center">\n                            <span class="material-symbols-outlined text-info" style="font-size: 2rem;">calendar_today</span>\n                        </div>\n                        <div>\n                            <div class="text-muted fw-bold h5">Última Actualización</div>\n                            <div class="fw-semibold h4">${formatoRelativo(e)}</div>\n                            <div class="text-muted h6">${formatoFechaCorta(e)}</div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    `;$("#stats").empty().html(n)}function formatoFechaCorta(t){return""===t?"":`${String(t.getDate()).padStart(2,"0")}/${String(t.getMonth()+1).padStart(2,"0")}/${t.getFullYear()}`}function formatoRelativo(t){if(""===t)return"";const s=new Date,e=new Date(s.getFullYear(),s.getMonth(),s.getDate())-new Date(t.getFullYear(),t.getMonth(),t.getDate()),n=Math.floor(e/864e5),a=t.toLocaleTimeString("es-ES",{hour:"2-digit",minute:"2-digit"});return 0===n?`Hoy, ${a}`:1===n?`Ayer, ${a}`:`Hace ${n} días, ${a}`}$(document).on("change","#products",function(){const t=$(this).val();componentFilters.products=t,fetchStats(),fetchList()}),$(document).on("change","#locations",function(){const t=$(this).val();componentFilters.locations=t,fetchStats(),fetchList()});